        Console.WriteLine($"{sheet.Name}: {d.Kind} '{d.Name}' at C{from?.Column} R{from?.Row}");
        if (d.Kind == DrawingKind.Picture && d.GetImageBytes() is byte[] bytes)
            File.WriteAllBytes(Path.Combine(folder, $"{sheet.Name}-{d.Id}.img"), bytes);
